-- ============================================================
--  Миграция 005: «Глюк-атака» — ещё 90 вопросов (всего 140, по 20 на тему)
--
--  Вопросы — из «Викторина — новые вопросы.pdf», переделанные в формат
--  «4 варианта». Неверные варианты и пояснения дописаны.
--
--  Заливается ОДИН раз: факт заливки записывается в glitch_seeds.
--  Если потом удалить или поправить вопрос в админке, при следующем
--  старте контейнера он не вернётся. Вопрос с уже существующим
--  текстом тоже не добавится повторно.
--
--  Откат:
--    DELETE FROM glitch_questions WHERE question IN (... тексты отсюда ...);
--    DELETE FROM glitch_seeds WHERE name = '005-questions';
-- ============================================================

SET client_encoding = 'UTF8';

BEGIN;

CREATE TABLE IF NOT EXISTS public.glitch_seeds (
    name        varchar(40) PRIMARY KEY,
    applied_at  timestamptz NOT NULL DEFAULT now()
);

